from sys import stdin

def solve():
    data = stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    grid = []
    for _ in range(n):
        grid.append([int(next(it)) for _ in range(m)])

    count = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 0:
                # Check left
                if any(grid[i][k] == 1 for k in range(j)):
                    count += 1
                # Check right
                if any(grid[i][k] == 1 for k in range(j + 1, m)):
                    count += 1
                # Check up
                if any(grid[k][j] == 1 for k in range(i)):
                    count += 1
                # Check down
                if any(grid[k][j] == 1 for k in range(i + 1, n)):
                    count += 1

    print(count)

if __name__ == "__main__":
    solve()
"}

