t = int(input())
for _ in range(t):
    n = int(input())
    s = list(map(int, input().split()))

    dp = [1] * n  # dp[i] = max length ending at index i (0-indexed)

    for i in range(n):
        # i is 0-indexed, original index is i+1
        # Find all divisors of (i+1)
        for j in range(i+1):  # j is 0-indexed divisor
            if j+1 != 0 and (i+1) % (j+1) == 0:
                if s[j] < s[i]:
                    dp[i] = max(dp[i], dp[j] + 1)

    print(max(dp))
"}

