q = int(input())
for _ in range(q):
    n = int(input())
    s = list(map(int, input().split()))

    count = [0] * 12  # for powers 0 to 11 (2^0 to 2^11 = 2048)
    for num in s:
        if num > 2048:
            continue
        k = 0
        while num > 1:
            num //= 2
            k += 1
        count[k] += 1

    for k in range(11):
        if count[k] >= 2:
            carry = count[k] // 2
            count[k] %= 2
            count[k + 1] += carry

    if count[11] >= 1:
        print("YES")
    else:
        print("NO")
"}

