def find_color(x: int, y: int) -> str:
    # Check if on border (integral distance from origin)
    distance_squared = x**2 + y**2
    distance = distance_squared ** 0.5
    if distance.is_integer():
        return "black"

    # Check if both coordinates have the same parity (even or odd)
    if (x % 2 == 0 and y % 2 == 0) or (x % 2 == 1 and y % 2 == 1):
        return "black"
    else:
        return "white"

x, y = map(int, input().split())
print(find_color(x, y))
"}

