def find_color(x: int, y: int) -> str:
    """Determine the color of the area damaged by the given point.
    - Points on the border (where at least one coordinate is an integer) are black
    - Points with integral distance to the origin are black
    - Otherwise, the color alternates based on quadrant
    """
    if x % 1 == 0 or y % 1 == 0:
        return "black"

    # Distance to origin
    dist_sq = x**2 + y**2
    if dist_sq.is_integer():
        return "black"

    # Color alternates by quadrant
    if x > 0 and y > 0:
        return "black"
    elif x < 0 and y > 0:
        return "white"
    elif x < 0 and y < 0:
        return "black"
    elif x > 0 and y < 0:
        return "white"

    raise ValueError("Unexpected coordinates")

if __name__ == "__main__":
    x, y = map(int, input().split())
    print(find_color(x, y))
