z = 0
if k == 1:
    z = 1 + b * n
else:
    # Calculate z = k^n + b * (k^n - 1) / (k - 1)
    kn = pow(k, n)
    z = kn + b * (kn - 1) // (k - 1)

# Now find minimum m such that t * k^m + b * (k^m - 1) / (k - 1) >= z
# If k == 1:
#     t * 1^m + b * m >= z => t + b * m >= z
# else:
#     t * k^m + b * (k^m - 1) / (k - 1) >= z

if k == 1:
    # Linear growth: t + b * m >= z
    if t >= z:
        print(0)
    else:
        print((z - t + b - 1) // b)
else:
    # Exponential growth
    # We want: t * k^m + b * (k^m - 1) / (k - 1) >= z
    m = 0
    while True:
        current = t * pow(k, m) + b * (pow(k, m) - 1) // (k - 1)
        if current >= z:
            print(m)
            break
        m += 1
