    t, l, r = map(int, input().split())

    if t == 2:  # Reverse segment [l, r]
        # For each important value at position i, update its new position
        for idx, pos in enumerate(positions):
            if l <= pos <= r - 1:
                # Value at position pos moves to position r - (pos - l) = r - pos + l
                new_pos = r - pos + l
                positions[idx] = new_pos
    elif t == 1:  # Cyclic shift right segment [l, r]
        # For each important value at position i, update its new position
        for idx, pos in enumerate(positions):
            if l <= pos <= r - 1:
                # Value at position pos moves to position pos + 1, except the last one
                if pos + 1 < r:
                    new_pos = pos + 1
                else:
                    new_pos = r
                positions[idx] = new_pos

result = [str(a[pos - 1]) for pos in positions]
print(' '.join(result))
