import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))
        freq = [0] * m

        for _ in range(n):
            a = int(next(it))
            r = a % m
            freq[r] += 1

        ans = 0

        # Handle remainder 0
        ans += freq[0] > 0

        # Handle other remainders
        for r in range(1, m // 2 + 1):
            s = m - r
            if r == s:
                # r and s are same, can chain all together
                if freq[r] >= 1:
                    ans += 1
                elif freq[r] >= 2:
                    ans += 1
            else:
                # Pair r with s
                count = min(freq[r], freq[s])
                ans += count

                # Remaining elements need their own chains
                if freq[r] > count:
                    ans += freq[r] - count
                if freq[s] > count:
                    ans += freq[s] - count

        out_lines.append(str(ans))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

