import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    out_lines = []

    idx = 1
    for _ in range(t):
        n = int(data[idx])
        idx += 1

        # Calculate the number of games each team plays
        games_per_team = n - 1

        # Output format: n(n-1)/2 integers
        output = []

        # First, handle team vs team for i from 1 to n-1
        for i in range(1, n):
            # Team i vs team j where j > i
            for j in range(i + 1, n + 1):
                if i == 1:
                    # Team 1: balance wins and losses
                    # n = 3 example: Team 1 beats Team 2, Team 3 beats Team 1
                    # Team 1: wins = 1, losses = 1, score = 3
                    if j == 2:
                        output.append(1)  # Team 1 wins
                    elif j == 3:
                        output.append(-1)  # Team 1 loses
                    else:
                        # n > 3, more complex pattern
                        # Team 1 beats first half teams, loses to second half teams
                        if n % 2 == 0:
                            if j <= n // 2 + 1:
                                output.append(1)
                            else:
                                output.append(-1)
                        else:
                            # n is odd
                            if j <= n // 2 + 1:
                                output.append(1)
                            else:
                                output.append(-1)
                else:
                    # Team i where i > 1
                    if i % 2 == 1:
                        # Odd teams: same as team 1 pattern
                        if n % 2 == 0:
                            if j <= n // 2 + 1:
                                output.append(1)
                            else:
                                output.append(-1)
                        else:
                            if j <= n // 2 + 1:
                                output.append(1)
                            else:
                                output.append(-1)
                    else:
                        # Even teams: different pattern
                        # Team 2 for n = 3: beats Team 3, loses to Team 1
                        # Team 2: wins = 1, losses = 1, score = 3
                        if j == 2:
                            output.append(-1)
                        elif j == 3:
                            output.append(1)
                        else:
                            if n % 2 == 0:
                                if j <= n // 2:
                                    output.append(-1)
                                else:
                                    output.append(1)
                            else:
                                if j <= n // 2:
                                    output.append(-1)
                                else:
                                    output.append(1)

        out_lines.append(' '.join(map(str, output)) + ' ')

    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    solve()
