def solve():
    q = int(input())

    # We need to go up to 2^20 (since 2^20 = 1048576 is larger than 2^11 = 2048)
    # But actually we only need up to the highest power present

    for _ in range(q):
        n = int(input())
        elements = list(map(int, input().split()))

        # Count occurrences of each power of 2
        count = {}
        for s in elements:
            i = 0
            while 2 ** i < s:
                i += 1
            count[i] = count.get(i, 0) + 1

        # Work backwards from the highest power to 2048
        highest_power = max(count.keys())

        # We'll need to carry over counts up to the highest power
        final_count = {}  # Count at each power level after merging

        # Start from the highest power and work down to 0
        # Then from 0 up to 2048, we can carry over
        # Actually, better to work from the lowest power to highest

        # Reset counts
        count = {}
        for s in elements:
            i = 0
            while 2 ** i < s:
                i += 1
            count[i] = count.get(i, 0) + 1

        # Work from lowest power to highest
        for i in range(highest_power, -1, -1):
            # Carry forward pairs to the next higher level
            if i + 1 in count:
                count[i + 1] += count[i] // 2
            else:
                count[i + 1] = count[i] // 2

            # Update leftover at current level
            count[i] %= 2

        # Check if we have 2048
        if count.get(11, 0) >= 1:
            print("YES")
        else:
            print("NO")

solve()
