import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    T = int(next(it))
    out_lines = []

    for _ in range(T):
        n = int(next(it))
        m = int(next(it))

        # Total vertices is 3*n
        total_vertices = 3 * n

        # We can always find either a matching of size n or an independent set of size n
        # Let's try to find an independent set by picking vertices with degree < n
        degree = [0] * (total_vertices + 1)
        edges = []

        for _ in range(m):
            u = int(next(it))
            v = int(next(it))
            edges.append((u, v))
            degree[u] += 1
            degree[v] += 1

        # Pick vertices with degree < n as candidates for independent set
        independent_candidates = [i for i in range(1, total_vertices + 1) if degree[i] < n]

        # Try to find an independent set of size n using a different approach
        # Pick vertices from independent_candidates greedily
