            if neighbor in path:
                # We found a cycle
                index = path.index(neighbor)
                cycle = path[index:]
                path.clear()
                return cycle
            else:
                result = dfs(neighbor, v, path)
                if result is not None:
                    return result
                path.pop()

    return None

