n, m = map(int, input().split())
playlist = list(map(int, input().split()))

# Count how many songs each band from 1 to m has
counts = [0] * (m + 1)  # 1-indexed
for band in playlist:
    if 1 <= band <= m:
        counts[band] += 1

# Find the maximum k such that we can achieve at least k songs for each band
# We want to maximize k, so we can binary search on k
# The minimum number of changes will be n - m * k

# Since we have n songs, the maximum possible k is at most n // m
left = 0
right = n // m
max_k = 0

while left <= right:
    mid = (left + right) // 2

    # Check if we can achieve at least mid songs for each band
    # We need at least m * mid songs in total
    # Total songs = n

    # Extra songs we have: sum(max(counts[i] - mid, 0) for i in 1..m)
    # Required songs we need: sum(max(mid - counts[i], 0) for i in 1..m)

    extra = 0
    required = 0
    for i in range(1, m + 1):
        if counts[i] > mid:
            extra += counts[i] - mid
        elif counts[i] < mid:
            required += mid - counts[i]

    if required <= extra:
        max_k = mid
        left = mid + 1
    else:
        right = mid - 1

# Now construct the playlist
result = []
extra_map = {}
for i in range(1, m + 1):
    if counts[i] > max_k:
        # Extra songs we need to change
        extra_map[i] = counts[i] - max_k
    elif counts[i] < max_k:
        # Missing songs we need to add
        extra_map[i] = max_k - counts[i]
    else:
        extra_map[i] = 0

# First, add all the songs we need
for i in range(1, m + 1):
    result.extend([i] * counts[i])

# Now we need to add the missing songs and change the extra songs
# We'll go through each position in the original playlist
for song in playlist:
    if 1 <= song <= m:
        # If this song is from a band that has extra, we can change it
        if counts[song] > max_k:
            # Find a band that needs songs
            for needed_band in range(1, m + 1):
                if extra_map[needed_band] > 0:
                    result.append(needed_band)
                    counts[song] -= 1
                    extra_map[song] -= 1
                    extra_map[needed_band] -= 1
                    break
                elif extra_map[needed_band] < 0:
                    # This band needs songs, so we'll add them later
                    pass
    else:
        # This song is from an unwanted band, we can change it
        # Find a band that needs songs
        for needed_band in range(1, m + 1):
            if extra_map[needed_band] > 0:
                result.append(needed_band)
                extra_map[needed_band] -= 1
                break

print(max_k, n - m * max_k)
print(' '.join(map(str, result)))
