def is_dominated(subarray):
    from collections import Counter
    count = Counter(subarray)
    max_count = max(count.values())
    for num in count:
        if count[num] == max_count:
            return True  # This element is the unique maximum
    return False

def solve():
    import sys
    input = sys.stdin.read().split()
    data = list(map(int, input))

    T = data[0]
    ptr = 1

    results = []

    for _ in range(T):
        n = data[ptr]
        ptr += 1

        if n < 2:
            results.append(-1)
            continue

        a = data[ptr:ptr + n]
        ptr += n

        min_length = float('inf')

        for i in range(n - 1):
            for j in range(i + 1, n):
