# (x, y) grid, 1-indexed
# Store visited cells with the earliest step
visited = {}  # (x, y) -> step

robot_x = x0
robot_y = y0

for step in range(len(s)):
    # Store current position if not already visited
    if (robot_x, robot_y) not in visited:
        visited[(robot_x, robot_y)] = step

    # Execute command
    cmd = s[step]
    if cmd == 'U':
        robot_x -= 1
    elif cmd == 'D':
        robot_x += 1
    elif cmd == 'L':
        robot_y -= 1
    elif cmd == 'R':
        robot_y += 1

    # Check bounds
    if robot_x < 1 or robot_x > x or robot_y < 1 or robot_y > y:
        robot_x = robot_x  # Stay in place
        robot_y = robot_y

# Count results
results = [0] * (len(s) + 1)

for i in range(1, x + 1):
    for j in range(1, y + 1):
        if (i, j) == (x0, y0):
            # Mine at starting position, robot blows up at k=0
            results[0] += 1
        elif (i, j) in visited:
            # Mine at a cell visited at some step
            results[visited[(i, j)]] += 1
        else:
            # Mine at a cell never visited, robot completes all commands
            results[len(s)] += 1

