import sys

def solve() -> None:
    MOD = 998244353

    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    a = list(map(int, data[2:2+n]))

    # Count number of subsets that produce each XOR value with exactly i bits set
    result = [0] * (m + 1)

    for mask in range(1 << n):
        xor = 0
        for i in range(n):
            if mask & (1 << i):
                xor ^= a[i]
        bits = bin(xor).count('1')
        if bits <= m:
            result[bits] = (result[bits] + 1) % MOD

    print(' '.join(str(result[i]) for i in range(m + 1)))

if __name__ == "__main__":
    solve()
