import sys

def solve() -> None:
    k, b, n, t = map(int, sys.stdin.read().split())
    if k == 1:
        z = 1 + n * b
    else:
        k_pow_n = pow(k, n)
        z = k_pow_n + b * (k_pow_n - 1) // (k - 1)

    if k == 1:
        if t >= z:
            print(0)
        else:
            print((z - t + b - 1) // b)
    else:
        x = t
        s = 0
        while x < z:
            x = k * x + b
            s += 1
        print(s)

if __name__ == "__main__":
    solve()
