from collections import deque

def solve():
    s = input().strip()

    points = deque(s)
    operations = 0

    while True:
        to_delete = set()

        # Check all points
        for i in range(len(points)):
            color = points[i]

            # Left neighbor
            if i > 0 and points[i-1] != color:
                to_delete.add(i)

            # Right neighbor
            if i < len(points) - 1 and points[i+1] != color:
                to_delete.add(i)

        if not to_delete:
            break

        # Create new points list
        new_points = []
        for i, color in enumerate(points):
            if i not in to_delete:
                new_points.append(color)

        points = deque(new_points)
        operations += 1

    print(operations)

solve()
