def is_dominated(sub):
    """Check if a subarray is dominated"""
    counts = {}
    max_count = 0
    max_values = []  # values that have the maximum count

    for num in sub:
        counts[num] = counts.get(num, 0) + 1
        max_count = max(max_count, counts[num])

    # Get all values with max count
    max_values = [k for k, v in counts.items() if v == max_count]

    # Check if any value has a count greater than any other single value
    # A subarray is dominated if the most frequent value appears more than any other single value
    for val in max_values:
        if counts[val] > max(counts.values()):
            return True
    return False


def solve_case(n, a):
    """Find the shortest dominated subarray"""
    if n < 2:
        return -1

    # Check all subarrays
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            sub = a[i:i+length]
            if is_dominated(sub):
                return length
    return -1

