def process_input():
    # Read n and k
    line = input().split()
    n, k = int(line[0]), int(line[1])

    # Read user-entered address s
    s = input().strip()

    # Preprocess s: create a dictionary mapping each character to a list of positions
    char_to_positions = {}
    for idx, char in enumerate(s):
        if char not in char_to_positions:
            char_to_positions[char] = []
        char_to_positions[char].append(idx + 1)  # 1-indexed

    # Process each potential address
    for _ in range(n):
        c = input().strip()
        length = len(c)
        total = 0

        for i in range(1, length + 1):  # i is 1-indexed
            char = c[i - 1]
            if char in char_to_positions:
                # Find closest position j in char_to_positions[char] to i
                # Binary search for the closest
                positions = char_to_positions[char]
                left, right = 0, len(positions)
                while left < right:
                    mid = (left + right) // 2
                    if positions[mid] < i:
                        left = mid + 1
                    else:
                        right = mid
                # left is the first position >= i
                closest_left = positions[left - 1] if left > 0 else None
                closest_right = positions[left] if left < len(positions) else None

                if closest_left is None:
                    # i < all positions
                    total += abs(i - closest_right)
                elif closest_right is None:
                    # i > all positions
                    total += abs(i - closest_left)
                else:
                    # i is between two positions
                    total += min(abs(i - closest_left), abs(i - closest_right))
            else:
                # No such character exists in s
                total += length

