# Function to compute the maximum overlap between two strings
# Returns the length of the maximum suffix of a that matches the prefix of b
# (or 0 if no overlap)
def max_overlap(a, b):
    max_overlap = 0
    # Check suffixes of a against prefixes of b
    for i in range(1, min(len(a), len(b)) + 1):
        if a[-i:] == b[:i]:
            max_overlap = i
    return max_overlap

# Function to check if a given superstring is valid
# (contains all fragments as substrings, all characters distinct)
def is_valid(superstring, fragments):
    superstring_set = set(superstring)
    for frag in fragments:
        if frag not in superstring or len(frag) > len(superstring):
            return False
        # Check that all characters in frag are unique in superstring
        if len(frag) != len(set(frag)):
            return False
        for c in frag:
            if c in superstring_set:
                superstring_set.remove(c)
                if not superstring_set:
                    return False
    return True

# Try all permutations to find the one with minimum length
from itertools import permutations

for perm in permutations(fragments):
    superstring = ''.join(perm)
    if is_valid(superstring, fragments):
        print(superstring)
        break
