import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # Count occurrences of each remainder modulo m
        counts = [0] * m
        for num in a:
            counts[num % m] += 1

        ans = 0

        # For remainder 0: all elements can be in one array (0+0 divisible by m)
        ans = max(ans, 1)  # At least one array for remainder 0

        for r in range(1, m // 2 + 1):
            if r == m - r:
                # r = m/2, only when m is even
                if m % 2 == 0 and r == m // 2:
                    ans = max(ans, (counts[r] + 1) // 2)
            else:
                # Pair r with m-r
                ans = max(ans, max(counts[r], counts[m - r]))

        out_lines.append(str(ans))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

