        # If n is odd, we can do it with 0 ties using a cycle

        # For odd n: cycle pattern
        # 1 beats 2, 2 beats 3, ..., n-1 beats n, n beats 1
        if n % 2 == 1:
            for i in range(1, n + 1):
                for j in range(1, n + 1):
                    if i != j:
                        if i % 2 == 1:
                            if j % 2 == 1:
                                # i beats j
                                if (i - j) % n == 1 or (i - j) % n == -n + 1:
                                    results.append(1)
