            # For even n: almost cycle pattern with 2 ties
            for i in range(1, n + 1):
                for j in range(1, n + 1):
                    if i != j:
                        if (i - j) % n == 1:
                            results.append(1)
                        elif (i - j) % n == -n + 1:
                            results.append(-1)
                        else:
