import sys

def can_measure(d, marks):
    """Check if distance d can be measured"""
    # Check if we have a pair of marks that differ by d
    for mark in marks:
        if (mark + d) in marks:
            return True
    return False

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    l = int(data[1])
    x = int(data[2])
    y = int(data[3])

    marks = list(map(int, data[4:4+n]))
    marks_set = set(marks)

    # Check if we can measure both x and y
    measure_x = can_measure(x, marks_set)
    measure_y = can_measure(y, marks_set)

    if measure_x and measure_y:
        print(0)
        print()  # Empty line
    elif measure_x or measure_y:
        # Measure one, need to add the other
        if measure_x:
            needed = y
        else:
            needed = x

        print(1)
        print(needed)
    else:
        # Measure neither, need to add both
        print(2)
        print(x, y)

if __name__ == "__main__":
    solve()
