def compute_distances(n, edges):
    dist = [[float('inf')] * n for _ in range(n)]
    for a, b, w in edges:
        dist[a-1][b-1] = w
        dist[b-1][a-1] = w

    # Floyd-Warshall to compute all pairs shortest paths
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    return dist

def solve():
    t = int(input())

    for _ in range(t):
        k = int(input())
        total_nodes = 2 * k
        edges = []

        for _ in range(2 * k - 1):
            a, b, w = map(int, input().split())
            edges.append((a, b, w))

        # Compute all pairs distances
        dist = compute_distances(total_nodes, edges)

        # Flatten distances
        distances = []
        for i in range(total_nodes):
            for j in range(i+1, total_nodes):
                distances.append(dist[i][j])

        # Sort distances
        distances.sort()

        # G = minimum sum (k smallest distances)
        # B = maximum sum (k largest distances)
        G = sum(distances[:k])
        B = sum(distances[-k:])

        print(G, B)

solve()
