    apples = {}

    # Start with one apple at each node at time 0
    for i in range(1, n + 1):
        apples[(i, 0)] = apples.get((i, 0), 0) + 1

    # Simulate each second until all apples are gone
    time = 0
    result = 0

    while apples:
        next_apples = {}

        # For each apple at each node at current time, move it to its parent
        for (node, t), count in apples.items():
            if node == 1:
                # Apple at root, collected by Arcady
                result += 1
            else:
