                next_node = parents[node - 2]  # parents is 0-indexed for nodes 2..n
                next_t = t + 1
                next_apples[(next_node, next_t)] = next_apples.get((next_node, next_t), 0) + count

        # Annihilate: if count > 1, only 1 survives
        for (node, t), count in next_apples.items():
            if count > 1:
                next_apples[(node, t)] = 1

