    arr = list(map(int, input().split()))

    # Calculate adjacent sums
    sums = [arr[i] + arr[i+1] for i in range(n-1)]

    # Function to compute total diamonds for given x
    def total(x):
        a = [x]
        for i in range(1, n):
            a.append(sums[i-1] - a[-1])
        return sum(a)

    # Find the minimum valid x
    def is_valid(x):
        a = [x]
        for i in range(1, n):
            a.append(sums[i-1] - a[-1])
            if a[-1] < 0:
                return False
        return True

    # Find minimum x within range [0, original_x + m*k]
    left, right = 0, arr[0] + m * k + 1
    while left < right:
        mid = (left + right) // 2
        if is_valid(mid):
            right = mid
        else:
            left = mid + 1

    optimal_x = left
    print(optimal_x)

