    def is_valid(year, y):
        if year < 1989:
            return False
        if str(year).endswith(y):
            # Check if y was used as an abbreviation in any previous year
            for prev_year in range(1989, year):
                # Simulate what abbreviation prev_year would have chosen
                # Try suffixes from shortest to longest
                prev_y = None
                for k in range(1, len(str(prev_year)) + 1):
                    suffix = str(prev_year)[-k:]
                    if not prev_y:
                        prev_y = suffix
                    # prev_y is the abbreviation used
                    if prev_y == y:
                        return False
                # If we looped through all k and prev_y != y
                # Then prev_year didn't use y
            return True
        return False

    # Find the first valid year
    while True:
        if is_valid(year, y_str):
            return year
        year += 1


