import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = int(data[1])
    b = int(data[2])
    s = data[3] if len(data) > 3 else ''

    # Precompute whether s[i:j] appears in prefix s[0:k-1]
    can = [[False] * (n + 1) for _ in range(n + 1)]

    # Check all possible substrings and their presence in prefixes
    for i in range(n):
        for j in range(i, n):
            for k in range(i + 1, n + 1):
                if s[i:j+1] in s[0:k]:
                    can[i][j] = True
                    break

    # Dynamic programming
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        for j in range(i):
            # Consider substring s[j..i-1] (0-indexed)
            length = i - j
            if length == 1:
                dp[i] = min(dp[i], dp[j] + a)
