import bisect

def compute_F(c, s_pos):
    """c is a string, s_pos is a dict mapping chars to list of 1-indexed positions in s"""
    l = len(c)
    F = 0
    for i in range(l):
        ch = c[i]
        target = i + 1
        if ch not in s_pos:
            F += l
            continue
        lst = s_pos[ch]
        idx = bisect.bisect_left(lst, target)
        # idx is insertion point
        candidates = []
        if idx < len(lst):
            candidates.append(abs(lst[idx] - target))
        if idx > 0:
            candidates.append(abs(lst[idx - 1] - target))
        if candidates:
            F += min(candidates)
        else:
            F += l
    return F

def solve() -> None:
    import sys
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))
    s = next(it).lower()
    # s may have length k, but we'll verify
    s_pos = {}
    for j, ch in enumerate(s, start=1):
        if ch not in s_pos:
            s_pos[ch] = []
        s_pos[ch].append(j)
    out_lines = []
    for _ in range(n):
        c = next(it).lower()
        out_lines.append(str(compute_F(c, s_pos)))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

