s = input()

# Simulate the robot's path
current_x, current_y = x0, y0
path = {(current_x, current_y): 0}

for t in range(1, len(s) + 1):
    move = s[t-1]
    if move == 'L':
        current_y -= 1
    elif move == 'R':
        current_y += 1
    elif move == 'U':
        current_x -= 1
    elif move == 'D':
        current_x += 1

    # Check if the move was valid (within bounds)
    if 1 <= current_x <= x and 1 <= current_y <= y:
        if (current_x, current_y) not in path:
            path[(current_x, current_y)] = t

# Calculate the total number of tests
total_tests = x * y

# Initialize result array
test_counts = [0] * (len(s) + 1)

# For each mine position (each unique cell)
for x_mine in range(1, x + 1):
    for y_mine in range(1, y + 1):
        if (x_mine, y_mine) in path:
            step = path[(x_mine, y_mine)]
        else:
            step = len(s)
        test_counts[step] += 1

# Print the result
print(' '.join(map(str, test_counts)))
